arguments.command:
cd /tmp/vally-eval-trial-kOGQXm && mkdir -p docs/features/checkout-pricing .copilot-tracking/skraft-plans/pricing/details/2026-08-12 tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > docs/features/checkout-pricing/discount.feature <<'EOF'
@discount
Feature: Loyalty tier discount

  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold, each decided by an acceptance criterion below.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so no expected
  # value exists and there is deliberately NO scenario for it (see the test plan, open questions).

  @happy-path
  Scenario: Returning Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Returning Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Returning Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Returning Bronze customer has the reduction land on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Returning_Bronze_customer_is_charged_the_Bronze_price()
    {
        // Returning Bronze customer is charged the Bronze price
        var query = new CalculateLoyaltyDiscountQuery(SubtotalCents: 10000, LoyaltyTier: LoyaltyTier.Bronze);

        var quote = new CalculateLoyaltyDiscount().Handle(query);

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -20

